import axios from 'axios'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import { hasStoredSession, restoreStoredSession, setSessionTokens } from './apiClient'

const storageKey = 'familyveda.refreshToken'
const authResponse = {
  userId: 'synthetic-doctor-01',
  displayName: 'Synthetic Doctor',
  userType: 'Doctor',
  accessToken: 'synthetic-access-2',
  refreshToken: 'synthetic-refresh-2',
  accessTokenExpiresAt: '2026-10-04T12:00:00Z',
}

describe('session persistence across reloads', () => {
  beforeEach(() => sessionStorage.clear())
  afterEach(() => vi.restoreAllMocks())

  it('keeps only the refresh token for the tab and clears it on sign-out', () => {
    setSessionTokens({ accessToken: 'synthetic-access-1', refreshToken: 'synthetic-refresh-1' })

    expect(sessionStorage.getItem(storageKey)).toBe('synthetic-refresh-1')
    expect(JSON.stringify({ ...sessionStorage })).not.toContain('synthetic-access-1')
    expect(hasStoredSession()).toBe(true)

    setSessionTokens(null)
    expect(hasStoredSession()).toBe(false)
  })

  it('returns null without calling the API when nothing is stored', async () => {
    const post = vi.spyOn(axios, 'post')

    expect(await restoreStoredSession()).toBeNull()
    expect(post).not.toHaveBeenCalled()
  })

  it('re-issues the session and stores the rotated refresh token', async () => {
    sessionStorage.setItem(storageKey, 'synthetic-refresh-1')
    const post = vi.spyOn(axios, 'post').mockResolvedValue({ data: authResponse })

    const restored = await restoreStoredSession()

    expect(restored?.userId).toBe('synthetic-doctor-01')
    expect(post.mock.calls[0][1]).toEqual({ refreshToken: 'synthetic-refresh-1' })
    expect(sessionStorage.getItem(storageKey)).toBe('synthetic-refresh-2')
  })

  it('discards a refresh token the server rejects', async () => {
    sessionStorage.setItem(storageKey, 'synthetic-revoked')
    vi.spyOn(axios, 'post').mockRejectedValue(
      Object.assign(new Error('Unauthorized'), { isAxiosError: true, response: { status: 401 } }),
    )

    expect(await restoreStoredSession()).toBeNull()
    expect(hasStoredSession()).toBe(false)
  })

  it('keeps the refresh token when the API is unreachable', async () => {
    sessionStorage.setItem(storageKey, 'synthetic-refresh-1')
    vi.spyOn(axios, 'post').mockRejectedValue(Object.assign(new Error('Network Error'), { isAxiosError: true }))

    expect(await restoreStoredSession()).toBeNull()
    expect(hasStoredSession()).toBe(true)
  })
})
